19: // Initializes termbox library. This function should be called before any other functions.
20: // After successful initialization, the library must be finalized using 'Close' function.
21: //
22: // Example usage:
23: //
24: //	err := termbox.Init()
25: //	if err != nil {
26: //	        panic(err)
27: //	}
28: //	defer termbox.Close()
29: func Init() error {
30: 	if IsInit {
31: 		return nil
32: 	}
33: 
34: 	var err error
35: 
36: 	if runtime.GOOS == "openbsd" || runtime.GOOS == "freebsd" {
37: 		out, err = os.OpenFile("/dev/tty", os.O_RDWR, 0)
38: 		if err != nil {
39: 			return err
40: 		}
41: 		in = int(out.Fd())
42: 	} else {
43: 		out, err = os.OpenFile("/dev/tty", os.O_WRONLY, 0)
44: 		if err != nil {
45: 			return err
46: 		}
47: 		in, err = unix.Open("/dev/tty", unix.O_RDONLY, 0)
48: 		if err != nil {
49: 			out.Close() // Clean up output file descriptor on error
50: 			return err
51: 		}
52: 	}
53: 
54: 	// Fd clears the O_NONBLOCK flag. On systems where in and out are the
55: 	// same file descriptor (see above), that would be a problem, because
56: 	// the in file descriptor needs to be nonblocking. Save the Fd return
57: 	// value here so that we won't need to call Fd later after the in file
58: 	// descriptor has been made nonblocking (see below).
59: 	outfd = out.Fd()
60: 
61: 	err = setup_term()
62: 	if err != nil {
63: 		out.Close()
64: 		if runtime.GOOS != "openbsd" && runtime.GOOS != "freebsd" {
65: 			unix.Close(in)
66: 		}
67: 		return fmt.Errorf("termbox: error while reading terminfo data: %v", err)
68: 	}
69: 
70: 	signal.Notify(sigwinch, unix.SIGWINCH)
71: 	signal.Notify(sigio, unix.SIGIO)
72: 
73: 	err = setFdAsync(in)
74: 	if err != nil {
75: 		out.Close()
76: 		if runtime.GOOS != "openbsd" && runtime.GOOS != "freebsd" {
77: 			unix.Close(in)
78: 		}
79: 		return err
80: 	}
81: 
82: 	orig_tios, err = tcgetattr(outfd)
83: 	if err != nil {
84: 		out.Close()
85: 		if runtime.GOOS != "openbsd" && runtime.GOOS != "freebsd" {
86: 			unix.Close(in)
87: 		}
88: 		return err
89: 	}
90: 
91: 	tios := orig_tios
92: 	tios.Iflag &^= unix.IGNBRK | unix.BRKINT | unix.PARMRK |
93: 		unix.ISTRIP | unix.INLCR | unix.IGNCR |
94: 		unix.ICRNL | unix.IXON
95: 	tios.Lflag &^= unix.ECHO | unix.ECHONL | unix.ICANON |
96: 		unix.ISIG | unix.IEXTEN
97: 	tios.Cflag &^= unix.CSIZE | unix.PARENB
98: 	tios.Cflag |= unix.CS8
99: 	tios.Cc[unix.VMIN] = 1
100: 	tios.Cc[unix.VTIME] = 0
101: 
102: 	err = tcsetattr(outfd, tios)
103: 	if err != nil {
104: 		out.Close()
105: 		if runtime.GOOS != "openbsd" && runtime.GOOS != "freebsd" {
106: 			unix.Close(in)
107: 		}
108: 		return err
109: 	}
110: 
111: 	out.WriteString(funcs[t_enter_ca])
112: 	out.WriteString(funcs[t_enter_keypad])
113: 	out.WriteString(funcs[t_hide_cursor])
114: 	out.WriteString(funcs[t_clear_screen])
115: 
116: 	termw, termh = get_term_size(outfd)
117: 	back_buffer.init(termw, termh)
118: 	front_buffer.init(termw, termh)
119: 	back_buffer.clear()
120: 	front_buffer.clear()
121: 
122: 	go func() {
123: 		buf := make([]byte, 128)
124: 		for {
125: 			select {
126: 			case <-sigio:
127: 				for {
128: 					n, err := unix.Read(in, buf)
129: 					if err == unix.EAGAIN || err == unix.EWOULDBLOCK {
130: 						break
131: 					}
132: 					select {
133: 					case input_comm <- input_event{buf[:n], err}:
134: 						ie := <-input_comm
135: 						buf = ie.data[:128]
136: 					case <-quit:
137: 						return
138: 					}
139: 				}
140: 			case <-quit:
141: 				return
142: 			}
143: 		}
144: 	}()
145: 
146: 	IsInit = true
147: 	return nil
148: }
