157: // Finalizes termbox library, should be called after successful initialization
158: // when termbox's functionality isn't required anymore.
159: func Close() {
160: 	if !IsInit {
161: 		return
162: 	}
163: 
164: 	quit <- 1
165: 	out.WriteString(funcs[t_show_cursor])
166: 	out.WriteString(funcs[t_sgr0])
167: 	out.WriteString(funcs[t_clear_screen])
168: 	out.WriteString(funcs[t_exit_ca])
169: 	out.WriteString(funcs[t_exit_keypad])
170: 	out.WriteString(funcs[t_exit_mouse])
171: 	tcsetattr(outfd, orig_tios)
172: 
173: 	out.Close()
174: 	unix.Close(in)
175: 
176: 	// reset the state, so that on next Init() it will work again
177: 	termw = 0
178: 	termh = 0
179: 	input_mode = InputEsc
180: 	out = nil
181: 	in = 0
182: 	lastfg = attr_invalid
183: 	lastbg = attr_invalid
184: 	lastx = coord_invalid
185: 	lasty = coord_invalid
186: 	cursor_x = cursor_hidden
187: 	cursor_y = cursor_hidden
188: 	foreground = ColorDefault
189: 	background = ColorDefault
190: 	IsInit = false
191: }
