193: // Synchronizes the internal back buffer with the terminal.
194: func Flush() error {
195: 	// invalidate cursor position
196: 	lastx = coord_invalid
197: 	lasty = coord_invalid
198: 
199: 	update_size_maybe()
200: 
201: 	for y := 0; y < front_buffer.height; y++ {
202: 		line_offset := y * front_buffer.width
203: 		for x := 0; x < front_buffer.width; {
204: 			cell_offset := line_offset + x
205: 			back := &back_buffer.cells[cell_offset]
206: 			front := &front_buffer.cells[cell_offset]
207: 			if back.Ch < ' ' {
208: 				back.Ch = ' '
209: 			}
210: 			w := runewidth.RuneWidth(back.Ch)
211: 			if w == 0 || w == 2 && runewidth.IsAmbiguousWidth(back.Ch) {
212: 				w = 1
213: 			}
214: 			if *back == *front {
215: 				x += w
216: 				continue
217: 			}
218: 			*front = *back
219: 			send_attr(back.Fg, back.Bg)
220: 
221: 			if w == 2 && x == front_buffer.width-1 {
222: 				// there's not enough space for 2-cells rune,
223: 				// let's just put a space in there
224: 				send_char(x, y, ' ')
225: 			} else {
226: 				send_char(x, y, back.Ch)
227: 				if w == 2 {
228: 					next := cell_offset + 1
229: 					front_buffer.cells[next] = Cell{
230: 						Ch: 0,
231: 						Fg: back.Fg,
232: 						Bg: back.Bg,
233: 					}
234: 				}
235: 			}
236: 			x += w
237: 		}
238: 	}
239: 	if !is_cursor_hidden(cursor_x, cursor_y) {
240: 		write_cursor(cursor_x, cursor_y)
241: 	}
242: 	return flush()
243: }
