245: // Sets the position of the cursor. See also HideCursor().
246: func SetCursor(x, y int) {
247: 	if is_cursor_hidden(cursor_x, cursor_y) && !is_cursor_hidden(x, y) {
248: 		outbuf.WriteString(funcs[t_show_cursor])
249: 	}
250: 
251: 	if !is_cursor_hidden(cursor_x, cursor_y) && is_cursor_hidden(x, y) {
252: 		outbuf.WriteString(funcs[t_hide_cursor])
253: 	}
254: 
255: 	cursor_x, cursor_y = x, y
256: 	if !is_cursor_hidden(cursor_x, cursor_y) {
257: 		write_cursor(cursor_x, cursor_y)
258: 	}
259: }
