266: // Changes cell's parameters in the internal back buffer at the specified
267: // position.
268: func SetCell(x, y int, ch rune, fg, bg Attribute) {
269: 	if x < 0 || x >= back_buffer.width {
270: 		return
271: 	}
272: 	if y < 0 || y >= back_buffer.height {
273: 		return
274: 	}
275: 
276: 	back_buffer.cells[y*back_buffer.width+x] = Cell{ch, fg, bg}
277: }
