279: // Returns the specified cell from the internal back buffer.
280: // Returns an empty cell if coordinates are out of bounds.
281: func GetCell(x, y int) Cell {
282: 	if x < 0 || x >= back_buffer.width || y < 0 || y >= back_buffer.height {
283: 		return Cell{}
284: 	}
285: 	return back_buffer.cells[y*back_buffer.width+x]
286: }
