327: // Returns a slice into the termbox's back buffer. You can get its dimensions
328: // using 'Size' function. The slice remains valid as long as no 'Clear' or
329: // 'Flush' function calls were made after call to this function.
330: func CellBuffer() []Cell {
331: 	return back_buffer.cells
332: }
333: 
334: // After getting a raw event from PollRawEvent function call, you can parse it
335: // again into an ordinary one using termbox logic. That is parse an event as
336: // termbox would do it. Returned event in addition to usual Event struct fields
337: // sets N field to the amount of bytes used within 'data' slice. If the length
338: // of 'data' slice is zero or event cannot be parsed for some other reason, the
339: // function will return a special event type: EventNone.
340: //
341: // IMPORTANT: EventNone may contain a non-zero N, which means you should skip
342: // these bytes, because termbox cannot recognize them.
343: //
344: // NOTE: This API is experimental and may change in future.
345: func ParseEvent(data []byte) Event {
346: 	event := Event{Type: EventKey}
347: 	status := extract_event(data, &event, false)
348: 	if status != event_extracted {
349: 		return Event{Type: EventNone, N: event.N}
350: 	}
351: 	return event
352: }
353: 
354: // Wait for an event and return it. This is a blocking function call. Instead
355: // of EventKey and EventMouse it returns EventRaw events. Raw event is written
356: // into `data` slice and Event's N field is set to the amount of bytes written.
357: // The minimum required length of the 'data' slice is 1. This requirement may
358: // vary on different platforms.
359: //
360: // NOTE: This API is experimental and may change in future.
361: func PollRawEvent(data []byte) Event {
362: 	if len(data) == 0 {
363: 		panic("len(data) >= 1 is a requirement")
364: 	}
365: 
366: 	var event Event
367: 	if extract_raw_event(data, &event) {
368: 		return event
369: 	}
370: 
371: 	for {
372: 		select {
373: 		case ev := <-input_comm:
374: 			if ev.err != nil {
375: 				return Event{Type: EventError, Err: ev.err}
376: 			}
377: 
378: 			inbuf = append(inbuf, ev.data...)
379: 			input_comm <- ev
380: 			if extract_raw_event(data, &event) {
381: 				return event
382: 			}
383: 		case <-interrupt_comm:
384: 			event.Type = EventInterrupt
385: 			return event
386: 
387: 		case <-sigwinch:
388: 			event.Type = EventResize
389: 			event.Width, event.Height = get_term_size(outfd)
390: 			return event
391: 		}
392: 	}
393: }
394: 
395: // Wait for an event and return it. This is a blocking function call.
396: func PollEvent() Event {
397: 	// Constant governing macOS specific behavior. See https://github.com/nsf/termbox-go/issues/132
398: 	// This is an arbitrary delay which hopefully will be enough time for any lagging
399: 	// partial escape sequences to come through.
400: 	const esc_wait_delay = 100 * time.Millisecond
401: 
402: 	var event Event
403: 	var esc_wait_timer *time.Timer
404: 	var esc_timeout <-chan time.Time
405: 
406: 	// try to extract event from input buffer, return on success
407: 	event.Type = EventKey
408: 	status := extract_event(inbuf, &event, true)
409: 	if event.N != 0 {
410: 		copy(inbuf, inbuf[event.N:])
411: 		inbuf = inbuf[:len(inbuf)-event.N]
412: 	}
413: 	switch status {
414: 	case event_extracted:
415: 		return event
416: 	case esc_wait:
417: 		esc_wait_timer = time.NewTimer(esc_wait_delay)
418: 		esc_timeout = esc_wait_timer.C
419: 	}
420: 
421: 	for {
422: 		select {
423: 		case ev := <-input_comm:
424: 			if esc_wait_timer != nil {
425: 				if !esc_wait_timer.Stop() {
426: 					<-esc_wait_timer.C
427: 				}
428: 				esc_wait_timer = nil
429: 			}
430: 
431: 			if ev.err != nil {
432: 				return Event{Type: EventError, Err: ev.err}
433: 			}
434: 
435: 			inbuf = append(inbuf, ev.data...)
436: 			input_comm <- ev
437: 			status := extract_event(inbuf, &event, true)
438: 			if event.N != 0 {
439: 				copy(inbuf, inbuf[event.N:])
440: 				inbuf = inbuf[:len(inbuf)-event.N]
441: 			}
442: 			switch status {
443: 			case event_extracted:
444: 				return event
445: 			case esc_wait:
446: 				esc_wait_timer = time.NewTimer(esc_wait_delay)
447: 				esc_timeout = esc_wait_timer.C
448: 			}
449: 		case <-esc_timeout:
450: 			esc_wait_timer = nil
451: 
452: 			status := extract_event(inbuf, &event, false)
453: 			if event.N != 0 {
454: 				copy(inbuf, inbuf[event.N:])
455: 				inbuf = inbuf[:len(inbuf)-event.N]
456: 			}
457: 			if status == event_extracted {
458: 				return event
459: 			}
460: 		case <-interrupt_comm:
461: 			event.Type = EventInterrupt
462: 			return event
463: 
464: 		case <-sigwinch:
465: 			event.Type = EventResize
466: 			event.Width, event.Height = get_term_size(outfd)
467: 			return event
468: 		}
469: 	}
470: }
