641: func cell_to_char_info(c Cell) (attr word, wc [2]wchar) {
642: 	attr = get_ct(color_table_fg, int(c.Fg)) | get_ct(color_table_bg, int(c.Bg))
643: 	if c.Fg&AttrReverse|c.Bg&AttrReverse != 0 {
644: 		attr = (attr&0xF0)>>4 | (attr&0x0F)<<4
645: 	}
646: 	if c.Fg&AttrBold != 0 {
647: 		attr |= foreground_intensity
648: 	}
649: 	if c.Bg&AttrBold != 0 {
650: 		attr |= background_intensity
651: 	}
652: 
653: 	r0, r1 := utf16.EncodeRune(c.Ch)
654: 	if r0 == 0xFFFD {
655: 		wc[0] = wchar(c.Ch)
656: 		wc[1] = ' '
657: 	} else {
658: 		wc[0] = wchar(r0)
659: 		wc[1] = wchar(r1)
660: 	}
661: 	return
662: }
